package com.pnntrn.cctv;
import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import java.util.regex.*;
public class DigestCheck {
static String md5(String x)throws Exception{byte[] b=MessageDigest.getInstance("MD5").digest(x.getBytes(StandardCharsets.UTF_8));StringBuilder s=new StringBuilder();for(byte v:b)s.append(String.format("%02x",v&255));return s.toString();}
public static void main(String[] a)throws Exception{for(boolean qop:new boolean[]{false,true})try(ServerSocket server=new ServerSocket(0,1,InetAddress.getByName("127.0.0.1"))){
Thread t=new Thread(()->{try(Socket socket=server.accept()){BufferedReader reader=new BufferedReader(new InputStreamReader(socket.getInputStream(),StandardCharsets.UTF_8));for(int i=0;i<2;i++){String first=reader.readLine();String auth="";for(String h;!(h=reader.readLine()).isEmpty();)if(h.startsWith("Authorization:"))auth=h;
if(i==0){String challenge="RTSP/1.0 401 Unauthorized\r\nCSeq: 1\r\nWWW-Authenticate: Digest realm=\"fixture\", nonce=\"nonce\", algorithm=MD5"+(qop?", qop=\"auth,auth-int\"":"")+"\r\nContent-Length: 0\r\n\r\n";socket.getOutputStream().write(challenge.getBytes(StandardCharsets.UTF_8));socket.getOutputStream().flush();}
else{Map<String,String> p=new HashMap<>();Matcher m=Pattern.compile("(\\w+)=(?:\"([^\"]*)\"|([^,\\s]+))").matcher(auth);while(m.find())p.put(m.group(1),m.group(2)!=null?m.group(2):m.group(3));String uri=first.split(" ")[1];String expected=md5(md5("u@ser:fixture:p:ass")+":nonce:"+(qop?"00000001:"+p.get("cnonce")+":auth:":"")+md5("DESCRIBE:"+uri));boolean good=expected.equals(p.get("response"))&&uri.contains("sub%2Fpath?x=a%26b")&&"u@ser".equals(p.get("username"));String body="v=0\r\nm=video 0 RTP/AVP 96\r\n";socket.getOutputStream().write(("RTSP/1.0 "+(good?"200 OK":"403 Forbidden")+"\r\nContent-Length: "+body.length()+"\r\n\r\n"+body).getBytes(StandardCharsets.UTF_8));socket.getOutputStream().flush();}}
}catch(Exception e){throw new RuntimeException(e);}});t.setDaemon(true);t.start();RtspProbe.Result result=RtspProbe.test("rtsp://u%40ser:p%3Aass@127.0.0.1:"+server.getLocalPort()+"/sub%2Fpath?x=a%26b");if(!result.okay)throw new AssertionError(result.message);t.join(3000);System.out.println("Digest MD5 "+(qop?"qop=auth":"without qop")+" passed, including reserved credential/path characters");}}
}
